/** two-letter tiles for tools simple-icons no longer carries */
const letterTiles: Record<string, string> = {
  photoshop: "Ps",
  illustrator: "Ai",
  canva: "C",
  word: "W",
  excel: "X",
  powerpoint: "P",
  vscode: "VS",
};

/** Maps any spelling in the data files to a glyph key. */
export function techKey(name: string): string {
  const n = name.toLowerCase().replace(/[^a-z]/g, "");
  if (n.startsWith("html")) return "html";
  if (n.startsWith("css")) return "css";
  if (n.includes("javascript") || n === "js") return "javascript";
  if (n === "java") return "java";
  if (n.startsWith("python")) return "python";
  if (n.startsWith("node")) return "node";
  if (n.startsWith("express")) return "express";
  if (n.startsWith("laravel")) return "laravel";
  if (n.startsWith("angular")) return "angular";
  if (n.startsWith("bootstrap")) return "bootstrap";
  if (n.startsWith("flutter")) return "flutter";
  if (n.startsWith("spring")) return "spring";
  if (n.startsWith("mysql") || n.startsWith("sql")) return "mysql";
  if (n.startsWith("photoshop")) return "photoshop";
  if (n.startsWith("illustrator")) return "illustrator";
  if (n.startsWith("canva")) return "canva";
  if (n.startsWith("microsoftword") || n === "word") return "word";
  if (n.startsWith("microsoftexcel") || n === "excel") return "excel";
  if (n.startsWith("powerpoint")) return "powerpoint";
  if (n.includes("visualstudio") || n === "vscode") return "vscode";
  if (n.startsWith("qrcode")) return "qr";
  if (n.startsWith("rest")) return "braces";
  if (n === "git") return "git";
  if (n.startsWith("github")) return "github";
  if (n.startsWith("telegram")) return "telegram";
  if (n.startsWith("facebook")) return "facebook";
  return "code"; // generic fallback
}

function strokeProps(): SVGProps<SVGSVGElement> {
  return {
    fill: "none",
    stroke: "currentColor",
    strokeWidth: 1.8,
    strokeLinecap: "round",
    strokeLinejoin: "round",
  };
}

/** The glyph for a technology, category, or channel name. Decorative. */
export function TechIcon({
  name,
  className = "size-3.5",
}: {
  name: string;
  className?: string;
}) {
  const key = techKey(name);
  const tile = letterTiles[key];

  if (tile) {
    return (
      <span
        aria-hidden="true"
        className={`inline-grid shrink-0 place-items-center border border-current font-mono font-bold leading-none ${className} text-[0.4rem]`}
      >
        {tile}
      </span>
    );
  }

  const paths = strokePaths[key];
  const fill = brandPaths[key];

  if (paths) {
    return (
      <svg viewBox="0 0 24 24" aria-hidden="true" className={className} {...strokeProps()}>
        {paths.map((d) => (
          <path key={d} d={d} />
        ))}
      </svg>
    );
  }

  return (
    <svg
      viewBox="0 0 24 24"
      aria-hidden="true"
      className={className}
      fill={fill ? "currentColor" : "none"}
      fillRule={key === "qr" ? "evenodd" : undefined}
      {...(fill ? {} : strokeProps())}
    >
      <path d={fill ?? "m8 6-6 6 6 6"} />
      {!fill && <path d="m16 6 6 6-6 6" />}
    </svg>
  );
}

/** A technology chip: glyph + label, used for stacks and skill lists. */
export function TechBadge({ name }: { name: string }) {
  return (
    <span className="tech-chip">
      <TechIcon name={name} />
      {name}
    </span>
  );
}

export type SocialKind =
  | "github"
  | "telegram"
  | "facebook"
  | "mail"
  | "phone"
  | "pin"
  | "cap"
  | "pen"
  | "code"
  | "braces"
  | "qr"
  | "external"
  | "copy";

const socialToGlyph: Record<SocialKind, string> = {
  github: "github",
  telegram: "telegram",
  facebook: "facebook",
  mail: "mail",
  phone: "phone",
  pin: "pin",
  cap: "cap",
  pen: "pen",
  code: "code",
  braces: "braces",
  qr: "qr",
  external: "external",
  copy: "copy",
};

/** Larger stroke/fill glyph for channels and section headers. Decorative. */
export function SocialIcon({
  kind,
  className = "size-4",
}: {
  kind: SocialKind;
  className?: string;
}) {
  const key = socialToGlyph[kind];
  const paths = strokePaths[key];
  const fill = brandPaths[key];

  if (paths) {
    return (
      <svg viewBox="0 0 24 24" aria-hidden="true" className={className} {...strokeProps()}>
        {paths.map((d) => (
          <path key={d} d={d} />
        ))}
      </svg>
    );
  }

  return (
    <svg viewBox="0 0 24 24" aria-hidden="true" className={className} fill="currentColor">
      <path d={fill} />
    </svg>
  );
}
